import{z as A,x as l,o as n,c as p,q as t,j as B,D as r,d as e,s,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"相关性崩溃情景","description":"","frontmatter":{"title":"相关性崩溃情景","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/corr-break-scenario.md","filePath":"quant/corr-break-scenario.md","lastUpdated":1791063341000}'),d={name:"quant/corr-break-scenario.md"};function h(g,a,c,m,u,C){const o=l("Mermaid");return n(),p("div",null,[a[2]||(a[2]=t('<h1 id="相关性崩溃情景" tabindex="-1">相关性崩溃情景 <a class="header-anchor" href="#相关性崩溃情景" aria-label="Permalink to &quot;相关性崩溃情景&quot;">​</a></h1><div class="epigraph"><p>危机里「相关升到 1」是观测现象；风控要把它写成可复现的因子移动：哪一篮子必须同向、波动是否先标准化、以及这是历史回放还是假设冲击。</p><footer>—— 现象见 Longin–Solnik、Forbes–Rigobon、Loretan–English；情景构造对照 Brunnermeier 对融资螺旋的叙述</footer></div><p><a href="/quant/reverse-stress-test">反向压力测试</a>收在逆问题要靠经济结构筛；相关这条轴的情景构造，是本篇的落地。<a href="/quant/correlation-breakdown">相关性崩溃</a> 一文写现象：下行 exceedance correlation、异方差把传染测高、融资与火线抛售让分散化失效。本篇不重复那条证据链，只写<strong>如何把崩溃做成压力引擎里的一条情景</strong>：输入今日头寸，输出一条或一组 \\(x\\)，使指定篮子的共同运动达到预声明的强度，并与日常 DCC、Copula VaR、反向压力测试共用同一套 \\(g\\)。Loretan 与 English 早已警告：若不先定义压力期与波动调整，「correlation breakdown」可以在任何样本里被搜出来。情景若也在数据里搜最大相关段，只是把同一错误写进限额。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日常 \\(\\Sigma_t\\) 或 DCC 的 \\(R_t\\) 给出条件线性相关。压力日组合损失远大于 \\(w^\\top\\Sigma_t w\\)，因为：（1）波动升，Forbes–Rigobon 偏差让滚动相关跳升；（2）真尾依赖升高；（3）融资约束让可抵押篮子被同时卖出。限额系统不能在崩溃当天再估一张 \\(\\Sigma\\)，必须预先有一条<strong>不依赖当天实现</strong>的规则：哪些名字被当成同一篮子、篮子内相关升到多少、篮子外是否保持、波动乘多少。</p><p><span class="marginnote">术语翻译：相关性崩溃指「平时相关不高的资产，在暴跌时一起跌」。例如平时股债相关约 \\(-0.2\\)，2020 年 3 月现金短缺时两者被同向抛售。风控不能等崩溃当天再估相关，必须预先把「哪些资产算一篮」写成规则。</span></p><p>问题不是「把全市场 \\(\\rho\\) 乘 1.5」。那会错误惩罚真正的对冲腿（某些趋势、期权、黄金），也会放过「表面上分散、融资上同一抵押」的集中。情景要按<strong>机制篮子</strong>切：经纪商可接受的抵押、同一 CTA 信号、同一信用指数成份，而不是按行业分类表机械加相关。</p><h3 id="三种合法构造-不要混成一个旋钮" tabindex="-1">三种合法构造，不要混成一个旋钮 <a class="header-anchor" href="#三种合法构造-不要混成一个旋钮" aria-label="Permalink to &quot;三种合法构造，不要混成一个旋钮&quot;">​</a></h3><p><strong>历史回放。</strong> 把 2008 年 9–10 月、2015 年 8 月、2020 年 3 月的因子变化套在今日头寸上。相关结构是那段历史自己的，不是你估出来的。优点是无可争议的已实现联合；缺点是头寸换了之后，那段历史未必仍是最坏相关。<strong>假设冲击。</strong> 指定篮子 \\(B\\)，令 \\(R_{ij}\\leftarrow 1-\\varepsilon\\) 对 \\(i,j\\in B\\)，其余块保持日常 \\(R_t\\)，再配波动乘数。<strong>Copula 角落。</strong> 保持边缘，把 \\(t\\) Copula 的 \\(\\nu\\) 降到很低或把 Clayton 参数推到样本外，抽联合极端。第一种是回放，后两种是判断。报告必须分开，不能把假设冲击的损失叫做「历史压力」。</p><p><span class="marginnote">先把收益用压力期或日常 \\(\\sigma\\) 标准化，再改相关，最后再乘回波动。把「未标准化的一起跌」直接写成相关情景，会把波动冲击与相关冲击算两遍，或算错遍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>篮子清单预先冻结。</strong> 例如：股指与高贝塔成份、信用指数与成份 CDS、基差交易的现券与期货、风险平价的股债商品外汇、境内可抵押回购券。每只篮子写触发叙事（保证金上调、赎回、指数剔除）。同一名字可属于多个篮子；情景一次只激活一个主篮子，另做「多篮子同时激活」的组合情景，避免相关矩阵被改到不正定却说不清是谁。</p><p><strong>矩阵手术。</strong> 在相关矩阵上把子块抬向 1，须做谱投影或收缩，保证正定。简单做法是：篮子内写成单因子，\\(x_i=\\beta_i F+\\varepsilon_i\\)，把 \\(\\mathrm{Var}(F)\\) 升到使两两相关达到目标，特异方差按比例缩小。这比逐元素改 \\(\\rho_{ij}\\) 更干净。目标相关不要写 1.00，写 0.85 或 0.9 并做敏感性；字面 \\(\\rho=1\\) 会让对冲腿的残差为零，造成虚假完美对冲或虚假无穷损失，取决于符号。</p><p><strong>波动与跳。</strong> 相关崩溃几乎总与波动跳升同时发生。情景应给 \\(\\sigma\\) 乘数（例如 2×、3×）或直接用压力年的已实现波动，并单独加一条跳：指数缺口、信用跳违约。只用相关、不改波动，会低估期权与 CPPI 缺口；只改波动、不改相关，会低估看似分散的线性账簿。BN 跳跃检验提供「跳日」清单，可当回放子集，但假设情景不应在全历史里搜 \\(Z\\) 最大的日子——那是数据挖掘。</p><h3 id="校准目标来自现象文献-不是来自优化器" tabindex="-1">校准目标来自现象文献，不是来自优化器 <a class="header-anchor" href="#校准目标来自现象文献-不是来自优化器" aria-label="Permalink to &quot;校准目标来自现象文献，不是来自优化器&quot;">​</a></h3><p>Longin–Solnik、Ang–Chen 的下行 exceedance correlation 给假设冲击一个数量级：从平静期 0.3 走到压力期 0.7 一类，而不是从 0.3 走到 1。Forbes–Rigobon 要求报告「除波动后相关是否仍升」：若标准化后相关几乎不变，情景应以波动冲击为主，不要强行改 \\(R\\)。Brunnermeier 的叙事给篮子：可抵押、被经纪商接受、被同一风险模型减仓的名字。校准是把文献数字写成参数范围，不是拟合一条使当前资本最大的相关路径——后者是反向压力的近亲，须声明。</p><p><span class="marginnote">数字实例：文献里下行 exceedance 相关的量级是从平静期约 0.3 升到压力期约 0.7，不是 1。篮子目标写成 0.85–0.9 再做敏感性，比写 1.00 诚实：\\(\\rho=1\\) 会让对冲腿残差归零，输出虚假的完美对冲或虚假的无穷损失。</span></p><p>与 DCC、Copula VaR 的日常数字对照：情景损失应高于日常 99% VaR 一个预先讨论过的倍数；若不高，说明篮子切错或头寸本来就极集中，相关改不动总风险。若过高到定价器崩溃，先检查正定与映射，再检查是否误把对冲腿也抬成同号。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>统计层：共同因子方差上升时，即使载荷不变，线性相关上升。情景里「升 \\(\\mathrm{Var}(F)\\)」就是在写这个。额外的传染是新因子（融资）出现：原来正交的残差被同一个 haircut 绑在一起。机制篮子存在的理由是捕捉这第二个因子，而不是把 \\(\\sigma_F\\) 再乘一次。</p><p><span class="marginnote">直觉类比：火线抛售像剧院失火——平时各走各门的人（正交的残差）此刻都挤向同一个出口（可抵押篮子）。「一起移动」不是大家的性格变了，是出口只剩一个；情景的任务是把这条出口写进矩阵。</span></p><p>经济层：火线抛售的冲击作用在被同时卖的篮子上，Kyle 的 \\(\\lambda\\) 让价格同向。相关矩阵的手术是对这一价格同向的线性近似。它不会自动包含流动性枯竭（买卖价差炸开、深度下降）。完整情景应同时降低可成交量或提高冲击函数，否则线性账簿的损失对、但执行与补保仍按平静期假设，现金会先于 VaR 耗尽。</p><p>一轮火线抛售如何自我放大：</p>',23)),(n(),B(i,null,{default:r(()=>[s(o,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%A4%96%E7%94%9F%E5%86%B2%E5%87%BB%3A%20%E4%BF%9D%E8%AF%81%E9%87%91%E4%B8%8A%E8%B0%83%20%2F%20%E8%B5%8E%E5%9B%9E%22%5D%20--%3E%20B%5B%22%E7%81%AB%E7%BA%BF%E6%8A%9B%E5%94%AE%E5%90%8C%E4%B8%80%E6%89%B9%E5%8F%AF%E6%8A%B5%E6%8A%BC%E7%AF%AE%E5%AD%90%22%5D%0A%20%20B%20--%3E%20C%5B%22Kyle%20%CE%BB%3A%20%E4%BB%B7%E6%A0%BC%E5%90%8C%E5%90%91%E4%B8%8B%E5%8E%8B%22%5D%0A%20%20B%20--%3E%20D%5B%22haircut%20%E6%8A%8A%E6%AD%A3%E4%BA%A4%E6%AE%8B%E5%B7%AE%E7%BB%91%E5%AE%9A%22%5D%0A%20%20C%20--%3E%20E%5B%22%E7%AF%AE%E5%AD%90%E5%86%85%E7%9B%B8%E5%85%B3%E4%B8%8A%E5%8D%87%22%5D%0A%20%20D%20--%3E%20E%0A%20%20E%20--%3E%20F%5B%22vol%20target%20%E4%B8%8E%E9%A3%8E%E9%99%A9%E5%B9%B3%E4%BB%B7%E5%90%8C%E6%AD%A5%E5%87%8F%E4%BB%93%22%5D%0A%20%20F%20--%3E%20G%5B%22%E7%AC%AC%E4%BA%8C%E8%BD%AE%E6%8A%9B%E5%94%AE%3A%20%E7%9B%B8%E5%85%B3%E4%B8%8E%E6%8B%A5%E6%8C%A4%E4%BA%92%E7%9B%B8%E6%94%BE%E5%A4%A7%22%5D%0A%20%20E%20--%3E%20H%5B%22%E5%8F%AA%E6%94%B9%20%CE%A3%20%E4%B8%8D%E6%94%B9%E6%B5%81%E5%8A%A8%E6%80%A7%3A%20%E7%8E%B0%E9%87%91%E5%85%88%E4%BA%8E%20VaR%20%E8%80%97%E5%B0%BD%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">风险平价与 vol target 在相关崩溃里不是被动受害者：规则本身在 \\(\\sigma\\) 上升时制造同步减仓，相关与拥挤互相放大。情景若只改 \\(\\Sigma\\)、不改这些规则的内生流量，会低估第二轮。</span></p><h3 id="与反向压力如何衔接" tabindex="-1">与反向压力如何衔接 <a class="header-anchor" href="#与反向压力如何衔接" aria-label="Permalink to &quot;与反向压力如何衔接&quot;">​</a></h3><p>正向相关情景问「若篮子 \\(B\\) 相关升到 0.9，我们亏多少」。反向问「要达到 \\(L^\\star\\)，相关最少要升到哪、还是其实一个名字就够」。两者共用篮子清单。若反向优化总是走单一名称而非相关崩溃，说明当前组合的真正风险是集中度，相关情景是次要的——应改限额，而不是把相关乘数调到能「看见」崩溃为止。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>高维正定、缺失历史、停牌与涨跌停，使回放不可交易：指数路径你复制不出。假设冲击在新兴市场、商品、加密上更依赖判断，因为压力样本短。t Copula 对称尾会在上涨端也制造假同涨，对冲评估会偏。工程折中：日常仍用 DCC 或收缩 \\(\\Sigma\\)；周频压力引擎跑冻结的历史回放 + 两到三个假设篮子冲击；反向压力另册。</p><p>不要把「股债相关转正」写成全球所有资产相关为 1。不要用指数相关替代可交易成份组合相关。不要在同一张情景里既把波动乘 3 又把未标准化相关拉到 1 却不做诊断。不要用情景损失去反推一个「隐含相关」再当 alpha。</p><p><span class="marginnote">情景参数（篮子、目标 \\(\\rho\\)、\\(\\sigma\\) 乘数）与候选策略网格一样，不能看完结果再挑最温和的那组。冻结、敏感性、与 2008/2020 回放并列，是最低治理。</span></p>',7)),(n(),B(i,null,{default:r(()=>[s(o,{id:"mermaid-89",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E9%A2%84%E5%85%88%E5%86%BB%E7%BB%93%E7%9A%84%E6%9C%BA%E5%88%B6%E7%AF%AE%E5%AD%90%22%5D%20--%3E%20H%5B%22%E5%8E%86%E5%8F%B2%E5%9B%9E%E6%94%BE%3A%202008%20%2F%202020%22%5D%0A%20%20B%20--%3E%20A%5B%22%E5%81%87%E8%AE%BE%E5%86%B2%E5%87%BB%3A%20%E5%AD%90%E5%9D%97%E7%9B%B8%E5%85%B3%E6%8A%AC%E5%8D%87%22%5D%0A%20%20B%20--%3E%20C%5B%22Copula%20%E8%A7%92%E8%90%BD%3A%20%CE%BD%20%E6%88%96%20%CE%BB%22%5D%0A%20%20H%20--%3E%20X%5B%22%E5%9B%A0%E5%AD%90%E6%83%85%E6%99%AF%20x%22%5D%0A%20%20A%20--%3E%20X%0A%20%20C%20--%3E%20X%0A%20%20VOL%5B%22%E6%B3%A2%E5%8A%A8%E4%B9%98%E6%95%B0%20%2F%20%E8%B7%B3%22%5D%20--%3E%20X%0A%20%20X%20--%3E%20G%5B%22%E4%B8%8E%E6%97%A5%E5%B8%B8%E4%B8%80%E8%87%B4%E7%9A%84%20g(x)%22%5D%0A%20%20G%20--%3E%20L%5B%22%E5%8E%8B%E5%8A%9B%E6%8D%9F%E5%A4%B1%20vs%20%E6%97%A5%E5%B8%B8%20VaR%22%5D%0A%20%20L%20--%3E%20CHK%5B%22%E5%AF%B9%E5%86%B2%E8%85%BF%E4%B8%8E%E6%AD%A3%E5%AE%9A%E6%80%A7%E6%A3%80%E6%9F%A5%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E("h2",{id:"小结",tabindex:"-1"},[e("小结 "),E("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=E("ul",null,[E("li",null,"相关性崩溃情景是预声明的因子移动规则，不是把全市场 \\(\\rho\\) 乘一个数，也不是在样本里搜最大相关段。"),E("li",null,"历史回放、假设篮子冲击、Copula 角落三种构造必须分开报告；先标准化波动再改相关。"),E("li",null,"篮子按融资与减仓同步机制切，目标相关用下行 exceedance 的数量级校准，并保持矩阵正定。"),E("li",null,"与日常 DCC/Copula VaR、反向压力共用 \\(g\\)；内生 vol target 流量应进入第二轮。"),E("li",null,[e("出处：Longin and Solnik, 2001；Ang and Chen, 2002；Forbes and Rigobon, 2002；Loretan and English, 2000；Brunnermeier, JEP 2009；现象综述见 "),E("a",{href:"/quant/correlation-breakdown"},"相关性崩溃"),e("。")])],-1))])}const _=A(d,[["render",h]]);export{b as __pageData,_ as default};
